-- The schema this chain leaves on a fresh database, printed from the catalogue.
-- Generated by `npm run schema:snapshot`; a test compares it with a fresh replay.

CREATE TABLE ee.iam_federation_issuer (
  id text NOT NULL,
  data bytea NOT NULL,
  org text NOT NULL,
  slug text NOT NULL,
  created_at timestamp with time zone NOT NULL,
  deleting_since timestamp with time zone,
  CONSTRAINT iam_federation_issuer_pkey PRIMARY KEY (id)
);
CREATE INDEX iam_federation_issuer_org_created ON ee.iam_federation_issuer USING btree (org, created_at DESC, id COLLATE "C" DESC);
CREATE UNIQUE INDEX iam_federation_issuer_org_slug ON ee.iam_federation_issuer USING btree (org, slug);

CREATE TABLE ee.iam_federation_issuer_route (
  issuer text NOT NULL,
  audience text NOT NULL,
  federation_issuer_id text NOT NULL,
  CONSTRAINT iam_federation_issuer_route_pkey PRIMARY KEY (issuer, audience)
);
CREATE INDEX iam_federation_issuer_route_issuer ON ee.iam_federation_issuer_route USING btree (federation_issuer_id);

CREATE TABLE ee.iam_invitation (
  id text NOT NULL,
  data bytea NOT NULL,
  org text NOT NULL,
  token text NOT NULL,
  created_at timestamp with time zone NOT NULL,
  CONSTRAINT iam_invitation_pkey PRIMARY KEY (id)
);
CREATE INDEX iam_invitation_org_created ON ee.iam_invitation USING btree (org, created_at DESC, id COLLATE "C" DESC);
CREATE UNIQUE INDEX iam_invitation_token ON ee.iam_invitation USING btree (token);

CREATE TABLE ee.iam_sign_in_grants (
  account_id text NOT NULL,
  org text NOT NULL,
  federation_issuer_id text NOT NULL,
  first_signed_in_at timestamp with time zone DEFAULT now() NOT NULL,
  CONSTRAINT iam_sign_in_grants_pkey PRIMARY KEY (account_id, org)
);
CREATE INDEX iam_sign_in_grants_org ON ee.iam_sign_in_grants USING btree (org);

CREATE TABLE ee.iam_team (
  id text NOT NULL,
  data bytea NOT NULL,
  org text NOT NULL,
  slug text NOT NULL,
  created_at timestamp with time zone NOT NULL,
  CONSTRAINT iam_team_pkey PRIMARY KEY (id)
);
CREATE INDEX idx_iam_team_org_created ON ee.iam_team USING btree (org, created_at DESC, id COLLATE "C" DESC);
CREATE UNIQUE INDEX uq_iam_team_org_slug ON ee.iam_team USING btree (org, slug);
